 41	  policy: CalculatorRequestBodyPolicy = CalculatorRequestBodyPolicy.make({
 42	    responseFormat: "json",
 43	  })
 44	) =>
 45	  Effect.gen(function* () {
 46	    const incoming = yield* HttpServerRequest.HttpServerRequest;
 47	    if (incoming.method !== "POST") {
 48	      return yield* handler;
 49	    }
 50	    const started = yield* Clock.monotonicTimeNanos;
 51	    const readResult = yield* incoming.stream.pipe(
 52	      Stream.mapAccumEffect(
 53	        () => ByteSize.bytes(0),
 54	        (total, chunk) => {
 55	          const next = ByteSize.sum(total, ByteSize.bytes(chunk.byteLength));
 56	          return ByteSize.isGreaterThan(next, CalculatorRequestBodyLimit)
 57	            ? Effect.fail(new CalculatorRequestBodyRejected({ reason: "size" }))
 58	            : Effect.succeed([next, [chunk]] as const);
 59	        }
 60	      ),
 61	      Stream.mkUint8Array,
 62	      Effect.timeoutOrElse({
 63	        duration: CalculatorRequestBodyDeadline,
 64	        orElse: () =>
 65	          Effect.fail(
 66	            new CalculatorRequestBodyRejected({ reason: "deadline" })
 67	          ),
 68	      }),
 69	      Effect.map(Result.succeed),
 70	      Effect.catchTag("CalculatorRequestBodyRejected", (error) =>
 71	        Effect.succeed(Result.fail(error))
 72	      )
 73	    );
 74	    const finished = yield* Clock.monotonicTimeNanos;
 75	    // Reject late synchronous reads once JavaScript returns control as well.
 76	    const read =
 77	      Result.isSuccess(readResult) &&
 78	      Duration.isGreaterThanOrEqualTo(
 79	        Duration.nanos(finished - started),
 80	        CalculatorRequestBodyDeadline
 81	      )
 82	        ? Result.fail(new CalculatorRequestBodyRejected({ reason: "deadline" }))
 83	        : readResult;
 84	    if (Result.isFailure(read)) {
 85	      const error =
 86	        read.failure.reason === "size"
 87	          ? new CalculatorRequestBodyTooLarge()
 88	          : new CalculatorRequestBodyTimedOut();
