 98	          <a href="/">Return to the calculators</a></main></body></html>`.pipe(
 99	          Effect.map((response) =>
100	            HttpServerResponse.setStatus(response, status)
101	          )
102	        );
103	      }
104	      return yield* HttpServerResponse.schemaJson(
105	        CalculatorRequestBodyErrorEnvelope
106	      )({ error }, { status }).pipe(Effect.orDie);
107	    }
108	    const bytes = read.success;
109	    const bounded = HttpServerRequest.toClientRequest(incoming)
110	      .pipe(
111	        HttpClientRequest.bodyUint8Array(
112	          bytes,
113	          Headers.get(incoming.headers, "content-type").pipe(
114	            Option.getOrUndefined
115	          )
116	        ),
117	        HttpServerRequest.fromClientRequest
118	      )
119	      .modify({ remoteAddress: incoming.remoteAddress, url: incoming.url });
120	    return yield* handler.pipe(
121	      Effect.provideService(HttpServerRequest.HttpServerRequest, bounded)
122	    );
123	  });

